head.script:

scwin.onpageload = function() {

};

scwin.onpageunload = function() {

};

//scope 함수
scwin.FormatterFunc = function (val) {

	return val +" 포매터 작동";

};

//전역함수
formatterFunc = function (val) {
	return val +" 포매터 작동";
};

scwin.checkVal1 = function() {
	return WebSquare.wUnit.getDomById('wq_uuid_9___input').value == 'a 포매터 작동';
}
scwin.checkVal2 = function() {
	return WebSquare.wUnit.getDomById('wq_uuid_13___input').value == 'a 포매터 작동';
}	
scwin.unitTest = function() {
	//init
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_9___input').click()");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_9___input').focus()");
	WebSquare.wUnit.addCommand("pause", "500");		
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_9___input').value = 'a'");
	WebSquare.wUnit.addCommand("pause", "500");		
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_13___input').click()");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_13___input').focus()");
	WebSquare.wUnit.addCommand("pause", "500");		
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
	WebSquare.wUnit.addCommand("pause", "500");		
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_13___input').value = 'a'");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_9___input').focus()");
	WebSquare.wUnit.addCommand("pause", "500");			
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
	WebSquare.wUnit.addCommand("pause", "500");

	//Run  and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest()
